layer.css:
@import url("https://fonts.googleapis.com/css?family=Abril+Fatface|PT+Sans:400,400i,700");
[data-ryt="pitch"] { color: rgb(122, 122, 122); border-left: 5px solid rgb(229, 229, 229); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 20px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(122, 122, 122); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 10px; padding-right: 100px; padding-bottom: 10px; padding-left: 25px; transition: all; border-top: none; border-right: none; border-bottom: none }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: var(--ryt-accent); border-radius: 0px; font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="hero"] h1 { color: rgb(49, 49, 49); font-family: var(--ryt-font-heading); font-size: 40px; font-weight: 700; font-style: normal; line-height: 1.25; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(49, 49, 49); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="brand"] { color: var(--ryt-bg); border-radius: 0px; font-family: "abril fatface", serif; font-size: 40px; font-weight: 700; font-style: normal; line-height: 1.25; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-bg); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="nav"] a { color: var(--ryt-bg); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 20px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-bg); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all }
[data-ryt="review"] { color: var(--ryt-text); font-family: var(--ryt-font-heading); font-size: 20px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="credit"], [data-ryt="eyebrow"] { color: var(--ryt-muted); font-family: var(--ryt-font-heading); font-size: 20px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-muted); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a { color: rgb(48, 48, 48); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 700; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(48, 48, 48); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] { color: rgb(48, 48, 48); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 34px; font-weight: 700; font-style: normal; line-height: 1.25; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(48, 48, 48); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a:hover { text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial }
[data-ryt="nav"] a:hover { text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial }
[data-ryt="credit"] a:hover, [data-ryt="review"] a:hover, [data-ryt="bio"] a:hover { text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial }
